class Oyyama < Formula
  desc "Large language model runner, interoperable with ollama"
  homepage "https://github.com/qzmfranklin/homebrew-tap"
  # Platform choice lives in the argument, not in an on_macos block:
  # brew does not allow `url`/`sha256` inside an on_system block.
  # macOS is one universal (arm64 + x86_64) binary, so it needs no arch split.
  url on_system_conditional(
    macos: "https://github.com/qzmfranklin/homebrew-tap/releases/download/oyyama-1.2.0/oyyama-1.2.0-darwin-universal.tar.xz",
    linux: on_arch_conditional(
      arm:   "https://github.com/qzmfranklin/homebrew-tap/releases/download/oyyama-1.2.0/oyyama-1.2.0-linux-arm64.tar.xz",
      intel: "https://github.com/qzmfranklin/homebrew-tap/releases/download/oyyama-1.2.0/oyyama-1.2.0-linux-amd64.tar.xz",
    ),
  )
  version "1.2.0"
  sha256 on_system_conditional(
    macos: "3888347975400d029a8f317a8c7e695cd00a9a98c8856536b1084ad5a017b43a",
    linux: on_arch_conditional(
      arm:   "8bccb357bfe0a4fc7b0cf8dd81c5e174c19d4eceab5456c19bec468c7ca9afb1",
      intel: "f3e810734e936d319793ed866211a8b9a706ac3f97c9880ba2813a0c8c63cdbf",
    ),
  )
  license :cannot_represent

  def install
    bin.install "oyyama"

    # Ad-hoc codesign on macOS. This is INTENTIONAL and load-bearing, not a
    # workaround: the binary is unsigned, and macOS refuses to exec an unsigned
    # or stale-signed Mach-O. Writing the file also invalidates any prior
    # signature, so it must be re-signed after install.
    #
    # chmod first: Homebrew stages files read-only, and both xattr and codesign
    # need to WRITE to the binary (xattr fails with EACCES otherwise).
    if OS.mac?
      chmod 0755, bin/"oyyama"
      system "/usr/bin/xattr", "-cr", bin/"oyyama"
      system "/usr/bin/codesign", "--force", "--sign", "-", bin/"oyyama"
    end
  end

  def post_install
    linked = HOMEBREW_PREFIX/"bin/oyyama"
    if linked.exist? && !linked.symlink?
      opoo <<~EOS
        Replacing a non-Homebrew oyyama at #{linked}.
        That file was almost certainly left by the legacy install script.
        The Homebrew-managed oyyama is now the one on your PATH.
      EOS
      linked.unlink
    end

    # Idempotent, and also repairs the case where the legacy binary was
    # deleted by hand: brew never created the symlink, so the tool was
    # missing from PATH entirely.
    linked.make_relative_symlink(bin/"oyyama") unless linked.symlink?
  end


  def caveats
    mac = on_macos do
      <<~EOS
        oyyama is interoperable with the community `ollama`: it reads the same model
        cache (OLLAMA_MODELS, ~/.ollama/models) and serves the same OpenAI-compatible
        API, so the two can coexist on one machine.

        Get started:
          oyyama pull qwen3:0.6b
          oyyama run qwen3:0.6b
      EOS
    end
    linux = on_linux do
      <<~EOS
        oyyama is interoperable with the community `ollama`: it reads the same model
        cache (OLLAMA_MODELS, ~/.ollama/models) and serves the same OpenAI-compatible
        API, so the two can coexist on one machine.

        Get started:
          oyyama pull qwen3:0.6b
          oyyama run qwen3:0.6b

        oyyama's linux binary is fully static (musl) — no glibc
        requirement; it runs on any linux the kernel supports. No
        interpreter, no shared libraries: the single binary is the whole
        install, on any distribution however old.
      EOS
    end
    mac || linux
  end

  test do
    # The CLI has no `version` subcommand (the default test assumes one), so
    # assert on --help instead, which exercises the binary end to end.
    assert_match "Large language model runner", shell_output("#{bin}/oyyama --help")
  end
end
